/*
  tableview.css
  ───────────────────────────────────────────────────────────────────────────
  Nutzt – wenn vorhanden – dieselben Variablen wie datepicker/selectpicker,
  bringt aber für jede einen eigenen Default mit, funktioniert also auch
  völlig allein:

    --clr-picker            Grundton (Popover, Gruppenzeilen)
    --clr-picker-input      Akzentfarbe (aktive Icons, Fokus)
    --br-picker             Border-Radius
    --fs-input-picker       Schriftgröße Eingaben
    --fs-picker-header      Schriftgröße Popover-Titel
    --height-input-picker   Höhe der Eingaben/Buttons

  Eigene Variablen:
    --tv-pop-width          Breite des Filter-Popovers (default 15rem)

  Alle internen Abstufungen (--_tv-*) werden per relativer Farbsyntax daraus
  berechnet und kollidieren nicht mit den Picker-internen Namen.
  ───────────────────────────────────────────────────────────────────────────
*/
@layer components {

  /* ── @font-face ─────────────────────────────────────────────────────────── */
  @font-face {
    font-family: 'Tableview Icons';
    font-style:  normal;
    font-weight: 400;
    /*ICONS: close refresh check search apps_outage chevron_left chevron_right*/
    src: url('data:font/woff2;base64,')
        format('woff2');
  }
  :root {
    /* ── Basiswerte: übernommen falls gesetzt, sonst Default ─────────────── */
    --_tv-base: var(--clr-picker,       light-dark(hsl(0, 0%, 90%), hsl(0, 0%, 10%)));
    --_tv-acc:  var(--clr-picker-input, light-dark(hsl(219, 100%, 50%), hsl(219, 100%, 30%)));
    --_tv-br:   var(--br-picker,           0.5rem);
    --_tv-fs:   var(--fs-input-picker,     0.9rem);
    --_tv-fs-h: var(--fs-picker-header,    1rem);
    --_tv-h:    var(--height-input-picker, 2rem);

    --tv-pop-width: 15rem;

    /* ── Abstufungen des Grundtons ───────────────────────────────────────── */
    --_tv-100: light-dark(hsl(from var(--_tv-base) h s 10%), hsl(from var(--_tv-base) h s 90%));
    --_tv-500: light-dark(hsl(from var(--_tv-base) h s 50%), hsl(from var(--_tv-base) h s 50%));
    --_tv-600: light-dark(hsl(from var(--_tv-base) h s 60%), hsl(from var(--_tv-base) h s 40%));
    --_tv-700: light-dark(hsl(from var(--_tv-base) h s 70%), hsl(from var(--_tv-base) h s 30%));
    --_tv-800: light-dark(hsl(from var(--_tv-base) h s 80%), hsl(from var(--_tv-base) h s 20%));
    --_tv-900: light-dark(hsl(from var(--_tv-base) h s 90%), hsl(from var(--_tv-base) h s 10%));

    /* ── Abstufungen der Akzentfarbe ─────────────────────────────────────── */
    --_tv-acc-100: light-dark(hsl(from var(--_tv-acc) h s 10%), hsl(from var(--_tv-acc) h s 90%));
    --_tv-acc-500: light-dark(hsl(from var(--_tv-acc) h s 50%), hsl(from var(--_tv-acc) h s 50%));
    --_tv-acc-900: light-dark(hsl(from var(--_tv-acc) h s 90%), hsl(from var(--_tv-acc) h s 10%));
  }

  .tv_msr {
    font-family:    'Material Symbols Rounded', 'Tableview Icons';
    font-weight:    normal;
    font-style:     normal;
    font-size:      24px;
    line-height:    1;
    letter-spacing: normal;
    text-transform: none;
    display:        inline-block;
    white-space:    nowrap;
    word-wrap:      normal;
    direction:      ltr;
    -moz-osx-font-smoothing: grayscale;
    -webkit-font-smoothing:  antialiased;
    font-variation-settings: 'FILL' 0, 'wght' 600, 'GRAD' 0, 'opsz' 24;

    &:hover { font-variation-settings: 'FILL' 1, 'wght' 600, 'GRAD' 0, 'opsz' 24; }
  }

  /* ── Hilfsklassen ───────────────────────────────────────────────────────── */
  .tv-hidden     { display: none !important; }
  .tv-col-hidden { display: none; }

  /* ── Tabelle ────────────────────────────────────────────────────────────── */
  table.tv-enabled {

    & th {
      user-select: none;

      &[t-sort] { cursor: pointer; }
    }

    /* Icon-Leiste in der Kopfzelle */
    & .tv-icons {
      display:        inline-flex;
      align-items:    center;
      gap:            0.15rem;
      margin-left:    0.35rem;
      vertical-align: middle;
    }

    & .tv-ico {
      display:         inline-flex;
      align-items:     center;
      justify-content: center;
      gap:             0.15rem;
      height:          1.5rem;
      min-width:       1.5rem;
      padding:         0;
      margin:          0;
      border:          none;
      background:      none;
      border-radius:   calc(var(--_tv-br) * 0.8);
      color:           var(--_tv-500);
      font-size:       1.1rem;
      line-height:     1;
      cursor:          pointer;
      transition:      background .15s, color .15s;

      &.tv-ico-active { color: var(--_tv-acc-500); }
    }

    /* Filter-Button: quadratisch – mit aktivem Filter rechteckig + Kurzinfo */
    & .tv-ico-filter {
      & .tv-filter-sum {
        display:     none;
        font-size:   0.7rem;
        line-height: 1;
        white-space: nowrap;
      }

      &.tv-ico-active {
        background: var(--_tv-acc-900);
        padding:    0 0.35rem 0 0.2rem;

        & .tv-filter-sum { display: inline; }
      }
    }

    /* ── Suchzeile ────────────────────────────────────────────────────────── */
    & .tv-search-row > th {
      padding:     0.25rem 0.4rem;
      font-weight: 400;
    }

    & .tv-search-wrap {
      display:       flex;
      align-items:   center;
      gap:           0.35rem;
      padding:       0.15rem 0.5rem;
      border:        1.5px solid var(--_tv-700);
      border-radius: var(--_tv-br);
      background:    var(--_tv-900);

      &:focus-within { border-color: var(--_tv-acc-500); }

      & .tv-search-icon,
      & .tv-search-clear { color: var(--_tv-500); font-size: 1.1rem; }

      & .tv-search-clear {
        cursor: pointer;

        &:hover { color: var(--_tv-100); }
      }

      & .tv-search-input {
        flex:       1;
        min-width:  0;
        border:     none;
        outline:    none;
        background: transparent;
        color:      var(--_tv-100);
        font:       inherit;
        font-size:  var(--_tv-fs);
        padding:    0.25rem 0;
      }
    }

    /* ── Gruppenzeilen ────────────────────────────────────────────────────── */
    & .tv-group-row > td {
      position:   relative;
      padding:    0;
      background: var(--_tv-800);
    }

    & .tv-group-content {
      display:     flex;
      align-items: center;
      gap:         0.4rem;
      padding:     0.35rem 2rem 0.35rem 1.25rem;
      cursor:      pointer;

      &:hover { background: var(--_tv-700); }

      & .tv-expand      { font-size: 1.1rem; color: var(--_tv-500); }
      & .tv-group-name  { font-weight: 600; }
      & .tv-group-label { font-weight: 400; color: var(--_tv-500); margin-right: 0.15rem; }

      & .tv-count {
        margin-left:   0.25rem;
        padding:       0.05rem 0.4rem;
        border-radius: 1rem;
        background:    var(--_tv-acc-900);
        color:         var(--_tv-acc-100);
        font-size:     0.75rem;
      }
    }

    & .tv-group-actions {
      position:    absolute;
      right:       2rem;
      top:         50%;
      translate:   0 -50%;
      display:     flex;
      align-items: center;
      gap:         0.25rem;
    }

    & .tv-ungroup {
      position:  absolute;
      right:     0.4rem;
      top:       50%;
      translate: 0 -50%;
      cursor:    pointer;
      font-size: 1.1rem;
      color:     var(--_tv-500);

      &:hover { color: var(--_tv-100); }
    }

    & .tv-empty {
      padding:    1rem;
      text-align: center;
      color:      var(--_tv-500);
      font-style: italic;
    }
  }

  /* ── Filter-Popover ─────────────────────────────────────────────────────── */
  .tv-pop {
    /* Browser-Default [popover]{inset:0; margin:auto} aushebeln – sonst wird
       das Popover ohne Anchor-Support über den ganzen Viewport gezogen und
       wirkt dadurch komplett leer. */
    position: fixed;
    position-area:  bottom;
    position-try: flip-y;
    position-try-fallbacks: flip-y;
    min-width:      anchor-size(width);
    margin-bottom:  0.25rem;
    margin-top:  0.25rem;
    
    inset:    auto;
    margin:   0;

    width:      var(--tv-pop-width);
    max-width:  calc(100vw - 1rem);
    height:     auto;
    max-height: calc(100dvh - 1rem);
    overflow-y: auto;
    overflow-x: hidden;
    box-sizing: border-box;

    padding:       0.6rem 0.75rem 0.75rem;
    border:        none;
    border-radius: calc(var(--_tv-br) * 1.5);
    background:    var(--_tv-900);
    color:         var(--_tv-100);
    box-shadow:    0rem 1rem 1.5rem hsl(from var(--_tv-base) h s 10% /0.5);
    font-family:   inherit;
    font-size:     var(--_tv-fs);
    line-height:   1.4;

    & * { box-sizing: border-box; }

    & .tv-pop-header {
      display:         flex;
      align-items:     center;
      justify-content: space-between;
      gap:             0.5rem;
      margin-bottom:   0.5rem;
      padding-bottom:  0.4rem;
      border-bottom:   1px solid var(--_tv-700);

      & .tv-pop-title {
        font-weight: 600;
        font-size:   var(--_tv-fs-h);
      }

      & .tv-pop-clear {
        display:       grid;
        place-items:   center;
        width:         var(--_tv-h);
        height:        var(--_tv-h);
        padding:       0;
        border:        none;
        background:    none;
        border-radius: calc(var(--_tv-br) * 0.8);
        color:         var(--_tv-500);
        font-size:     1.2rem;
        line-height:   1;
        cursor:        pointer;
        transition:    background .15s, color .15s;

        &:hover { background: var(--_tv-700); color: var(--_tv-100); }
      }
    }

    & .tv-pop-body {
      display:        flex;
      flex-direction: column;
      gap:            0.4rem;
    }

    & .tv-pop-field {
      display:        flex;
      flex-direction: column;
      gap:            0.15rem;

      & .tv-pop-label {
        font-size:      0.72rem;
        font-weight:    500;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color:          var(--_tv-500);
      }

      & .tv-pop-input {
        width:         100%;
        height:        var(--_tv-h);
        padding:       0.25rem 0.5rem;
        border:        1.5px solid var(--_tv-700);
        border-radius: calc(var(--_tv-br) * 0.7);
        background:    var(--_tv-900);
        color:         var(--_tv-100);
        font:          inherit;
        font-size:     var(--_tv-fs);

        &::-webkit-calendar-picker-indicator { cursor: pointer; }

        &:focus {
          outline:      none;
          border-color: var(--_tv-acc-500);
          box-shadow:   0 0 0 2px hsl(from var(--_tv-acc-500) h s l / 0.2);
        }
      }
    }
  }
}


/* Ohne Anchor-Positioning (aktuell z.B. Firefox/Safari): mittig einblenden. */
@supports not (position-area: bottom) {
  .tv-pop {
    inset:     50% auto auto 50%;
    translate: -50% -50%;
  }
}